#include <vector>
#include <string>
#include <algorithm>
#include <bitset>

class Solution {
    std::string to_bin(int x) {
        std::string s = "";
        while (x > 0) {
            s += (x % 2 ? '1' : '0');
            x /= 2;
        }
        std::reverse(s.begin(), s.end());
        return s;
    }
public:
    int maxGoodNumber(std::vector<int>& nums) {
        std::vector<std::string> b;
        for (int x : nums) b.push_back(to_bin(x));
        std::sort(b.begin(), b.end());
        int ans = 0;
        do {
            std::string s = b[0] + b[1] + b[2];
            int val = 0;
            for (char c : s) val = (val << 1) | (c - '0');
            ans = std::max(ans, val);
        } while (std::next_permutation(b.begin(), b.end()));
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxGoodNumber(int[] nums) {
        String[] bins = new String[3];
        for (int i = 0; i < 3; i++) bins[i] = Integer.toBinaryString(nums[i]);

        int[][] perms = {
            {0, 1, 2}, {0, 2, 1},
            {1, 0, 2}, {1, 2, 0},
            {2, 0, 1}, {2, 1, 0}
        };

        int ans = 0;
        for (int[] p : perms) {
            String cat = bins[p[0]] + bins[p[1]] + bins[p[2]];
            int val = Integer.parseInt(cat, 2);
            ans = Math.max(ans, val);
        }
        return ans;
    }
}

var maxGoodNumber = function(nums) {
    const bins = nums.map(x => x.toString(2));
    const perms = [
        [0, 1, 2], [0, 2, 1],
        [1, 0, 2], [1, 2, 0],
        [2, 0, 1], [2, 1, 0]
    ];
    let ans = 0;
    for (const p of perms) {
        const cat = bins[p[0]] + bins[p[1]] + bins[p[2]];
        const val = parseInt(cat, 2);
        if (val > ans) ans = val;
    }
    return ans;
};
